using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class SessionSecurityPage:UserControl{public SessionSecurityPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;var card=Ui.Card();card.Dock=DockStyle.Top;card.Height=310;var title=Ui.Label(L.Fa?"امنیت نشست و حساب":"Session & account security",18,true);title.Location=new Point(20,20);var info=Ui.Label((L.Fa?"کاربر: ":"User: ")+AppSession.Username+Environment.NewLine+(L.Fa?"نقش: ":"Role: ")+AppSession.Role+Environment.NewLine+(L.Fa?"شناسه نشست: ":"Session user ID: ")+AppSession.UserId+Environment.NewLine+(L.Fa?"اتصال دیتابیس: LocalDB با Windows Authentication":"Database: LocalDB with Windows Authentication"),11);info.Location=new Point(20,70);info.MaximumSize=new Size(700,0);var audit=Ui.Button(L.Fa?"ثبت بررسی امنیتی":"Log security review");audit.Location=new Point(20,190);audit.Click+=(s,e)=>{Database.Audit("SecurityReview","Session",AppSession.Username);MessageBox.Show(L.Fa?"رویداد امنیتی ثبت شد.":"Security event logged.");};card.Controls.AddRange(new Control[]{title,info,audit});Controls.Add(card);}}}